    final hiveService = sl<HiveService>();

    return ValueListenableBuilder(
      valueListenable: hiveService.folderBox.listenable(),
      builder: (context, Box<FolderModel> folderBox, _) {
        return ValueListenableBuilder(
          valueListenable: hiveService.fileBox.listenable(),
