                                  color: Color(0xFF2D2540),
                                ),
                              ),
                              const Spacer(),
                              _buildHeaderButton(
                                icon: Icons.search,
                                onPressed: () => context.push('/search'),
                              ),
                              const SizedBox(width: 8),
                              _buildHeaderButton(
                                icon: Icons.settings_outlined,
                                onPressed: () => context.push('/settings'),
                              ),
                            ],
                          ),
                        ),

                        // List Header Row
                        Padding(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 14, vertical: 8),
                          child: Row(
                            mainAxisAlignment: MainAxisAlignment.spaceBetween,
                            children: [
                              Text(
                                '${rootFolders.length} folders',
                                style: const TextStyle(
                                  fontSize: 11,
                                  fontWeight: FontWeight.w500,
                                  color: Color(0xFF9B8DB8),
                                ),
                              ),
                              Container(
                                padding: const EdgeInsets.symmetric(
                                    horizontal: 8, vertical: 4),
                                decoration: BoxDecoration(
                                  color: const Color(0xFFEDE9F8),
                                  borderRadius: BorderRadius.circular(7),
                                ),
                                child: const Row(
                                  children: [
                                    Icon(Icons.sort,
                                        size: 12, color: Color(0xFF6C5CE7)),
                                    SizedBox(width: 4),
                                    Text(
                                      'Recent',
                                      style: TextStyle(
                                        fontSize: 11,
                                        color: Color(0xFF6C5CE7),
                                        fontWeight: FontWeight.w500,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),

                        // Body List
                        Expanded(
                          child: ListView.builder(
                            padding: const EdgeInsets.only(top: 4, bottom: 20),
                            itemCount: allItems.length,
                            itemBuilder: (context, index) {
                              final item = allItems[index];
                              if (item is Folder) {
                                final folderItemsCount = fileBox.values
                                    .where((file) => file.folderId == item.id)
                                    .length;

                                return FolderCard(
                                  folder: item,
                                  noteCount: folderItemsCount,
                                );
                              } else if (item.runtimeType
                                  .toString()
                                  .contains('VaultFile')) {
                                return FileCard(file: item as dynamic);
                              } else {
                                // Fallback or legacy
                                return const SizedBox.shrink();
                              }
                            },
                          ),
                        ),

                        // Bottom CTA
                        Padding(
                          padding: const EdgeInsets.fromLTRB(14, 0, 14, 20),
                          child: SizedBox(
                            width: double.infinity,
                            child: ElevatedButton.icon(
                              onPressed: () => showCreateBottomSheet(context),
                              icon: const Icon(Icons.add, color: Colors.white),
                              label: const Text(
                                'Create new',
                                style: TextStyle(
                                  color: Colors.white,
                                  fontSize: 15,
                                  fontWeight: FontWeight.w500,
                                ),
                              ),
                              style: ElevatedButton.styleFrom(
                                backgroundColor: const Color(0xFF6C5CE7),
                                padding:
                                    const EdgeInsets.symmetric(vertical: 13),
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(14),
                                ),
                                elevation: 0,
                              ),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              },
            );
          },
        );
      },
    );
  }

