import 'package:flutter/material.dart';
import 'package:notepad_pro/core/utils/color_extensions.dart';

Future<Map<String, dynamic>?> showCreateFolderDialog(
  BuildContext context, {
  String? initialName,
  int? initialColorValue,
}) {
  final TextEditingController controller = TextEditingController(text: initialName);
  final GlobalKey<FormState> formKey = GlobalKey<FormState>();

  // Signature Purple is our Default
  const Color defaultColor = Colors.deepPurple;

  Color selectedColor = initialColorValue != null 
      ? Color(initialColorValue) 
      : defaultColor;

  final List<Color> curatedPalette = [
    // Pastels
    const Color(0xFFFFB3BA), // Red
    const Color(0xFFFFDFBA), // Orange
    const Color(0xFFFFFFBA), // Yellow
    const Color(0xFFBAFFC9), // Green
    const Color(0xFFBAE1FF), // Blue
    const Color(0xFFD0BAFF), // Purple
    const Color(0xFFE2BAFF), // Pink
    const Color(0xFFFFB2E6), // Rose
    const Color(0xFFB2F2FF), // Cyan
    const Color(0xFFB2FFD6), // Mint

    // Material 200s (Soft & Professional)
    Colors.red.shade200,
    Colors.pink.shade200,
    Colors.purple.shade200,
    Colors.deepPurple.shade200,
    Colors.indigo.shade200,
    Colors.blue.shade200,
    Colors.lightBlue.shade200,
    Colors.cyan.shade200,
    Colors.teal.shade200,
    Colors.green.shade200,
    Colors.lightGreen.shade200,
    Colors.lime.shade200,
    Colors.yellow.shade200,
    Colors.amber.shade200,
    Colors.orange.shade200,
    Colors.deepOrange.shade200,
    Colors.brown.shade200,
    Colors.grey.shade200,
    Colors.blueGrey.shade200,
    const Color(0xFF90A4AE), // Slate-ish
  ];

  return showDialog<Map<String, dynamic>>(
    context: context,
    builder: (context) {
      return AlertDialog(
        title: Text(initialName == null ? 'Create New Folder' : 'Edit Folder'),
        content: StatefulBuilder(
          builder: (BuildContext context, StateSetter setState) {
            return Form(
              key: formKey,
              autovalidateMode: AutovalidateMode.onUserInteraction,
              child: SizedBox(
                width: double.maxFinite,
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      TextFormField(
                        controller: controller,
                        autofocus: true,
                        decoration: const InputDecoration(
                          labelText: 'Folder Name',
                          hintText: 'e.g., Work, Personal, Travel, Ideas',
                          border: OutlineInputBorder(),
                        ),
                        validator: (value) {
                          if (value == null || value.trim().isEmpty) {
                            return 'Please enter a folder name';
                          }
                          if (value.trim().length < 2) {
                            return 'Name should be at least 2 characters';
                          }
                          return null;
                        },
                      ),
                      const SizedBox(height: 24),
                      Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Text(
                            'Select Color:',
                            style: Theme.of(context).textTheme.titleSmall?.copyWith(
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                          TextButton.icon(
                            onPressed: () => setState(() => selectedColor = defaultColor),
                            icon: const Icon(Icons.refresh, size: 16),
                            label: const Text('Default', style: TextStyle(fontSize: 12)),
                            style: TextButton.styleFrom(
                              visualDensity: VisualDensity.compact,
                              foregroundColor: Colors.deepPurple,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),
                      Wrap(
                        spacing: 10,
                        runSpacing: 10,
                        children: [
                          // Default Option Circle
                          _buildColorCircle(
                            color: defaultColor,
                            isSelected: selectedColor.value == defaultColor.value,
                            onTap: () => setState(() => selectedColor = defaultColor),
                            isDefault: true,
                          ),
                          // Palette Colors
                          ...curatedPalette.map((color) {
                            final bool isSelected = selectedColor.value == color.value;
                            return _buildColorCircle(
                              color: color,
                              isSelected: isSelected,
                              onTap: () {
                                setState(() {
                                  // Toggle logic: if clicking already selected, reset to default
                                  if (isSelected) {
                                    selectedColor = defaultColor;
                                  } else {
                                    selectedColor = color;
                                  }
                                });
                              },
                            );
                          }),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () {
              if (formKey.currentState?.validate() ?? false) {
                Navigator.of(context).pop({
                  'name': controller.text.trim(),
                  'colorValue': selectedColor.toARGB(),
                });
              }
            },
            child: Text(initialName == null ? 'Create' : 'Save'),
          ),
        ],
      );
    },
  );
}

Widget _buildColorCircle({
  required Color color,
  required bool isSelected,
  required VoidCallback onTap,
  bool isDefault = false,
}) {
  return GestureDetector(
    onTap: onTap,
    child: AnimatedContainer(
      duration: const Duration(milliseconds: 200),
      width: 40,
      height: 40,
      decoration: BoxDecoration(
        color: color,
        shape: BoxShape.circle,
        border: Border.all(
          color: isSelected ? Colors.black87 : Colors.black12,
          width: isSelected ? 2.5 : 1.0,
        ),
        boxShadow: isSelected ? [
          BoxShadow(
            color: color.withValues(alpha: 0.4),
            blurRadius: 6,
            spreadRadius: 1,
          )
        ] : null,
      ),
      child: isSelected 
          ? const Icon(Icons.check, color: Colors.black87, size: 20) 
          : (isDefault ? const Icon(Icons.star_outline, color: Colors.white70, size: 16) : null),
    ),
  );
}

