import 'package:notepad_pro/domain/entities/vault_file.dart';
import 'package:notepad_pro/domain/entities/search_result.dart';

class SearchHelper {
  static List<SearchResult> searchFiles({
    required String query,
    required List<VaultFile> allFiles,
    required String Function(String?) getFolderName,
    required String Function(DateTime) formatDate,
  }) {
    if (query.trim().isEmpty) return [];

    final String lowerQuery = query.toLowerCase();
    final List<SearchResult> results = [];

    for (final file in allFiles) {
      final String title = file.title;
      final String content = file.description;
      final String fullText = '$title $content'.toLowerCase();

      // Count total matches in both title and description
      int matchCount = 0;
      int pos = fullText.indexOf(lowerQuery);
      while (pos != -1) {
        matchCount++;
        pos = fullText.indexOf(lowerQuery, pos + lowerQuery.length);
      }

      if (matchCount > 0) {
        final String lowerContent = content.toLowerCase();

        // Snippet logic (for backward compatibility if needed)
        int firstMatchInContent = lowerContent.indexOf(lowerQuery);
        String snippet;
        const int maxLength = 150;

        if (firstMatchInContent == -1 || firstMatchInContent < maxLength) {
          snippet = content.length > maxLength 
              ? '${content.substring(0, maxLength)}...' 
              : content;
        } else {
          int start = firstMatchInContent - 40;
          if (start < 0) start = 0;

          int end = start + maxLength;
          if (end > content.length) end = content.length;
...

        results.add(SearchResult(
          file: file,
          snippet: snippet,
          matchCount: matchCount,
          noteId: file.id,
          title: title,
          content: content,
          folderName: getFolderName(file.folderId),
          dateLabel: formatDate(file.updatedAt),
          previewLines: extractPreviewLines(content, query),
        ));
      }
    }

    return results;
  }

  static List<String> extractPreviewLines(String content, String query) {
    final lines = content.split('\n')
      .where((l) => l.trim().isNotEmpty)
      .toList();

    final lowerQuery = query.toLowerCase();
    final matches = lines
      .where((l) => l.toLowerCase().contains(lowerQuery))
      .take(3)
      .toList();

    return matches.isEmpty
      ? lines.take(2).toList()
      : matches;
  }
}

