              ),
            ),

            // PLUS
            Expanded(
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: () {
                  int val = int.tryParse(controller.text) ?? 0;
                  if (val < max) {
                    val++;
                    controller.text = val.toString().padLeft(2, '0');
                    setState(() {
                      if (unit == "hours") _videoHours = val;
                      if (unit == "min") _videoMinutes = val;
