      final driveApi = await _getDriveApi();
      if (driveApi == null) throw Exception("Google Drive Authentication failed.");
      _progressController.add(0.05);

      // Step A & B: Root and Uncategorized Folder Setup
      final String appRootFolderId = await _getOrCreateDriveFolder(driveApi, 'Smart_Notes_Backup_Root');
      final String uncategorizedFolderId = await _getOrCreateDriveFolder(
          driveApi, 'Uncategorized Files',
          parentId: appRootFolderId);
      _progressController.add(0.1);

      // Step C: Folder Hierarchy Reconstruction
      final localFolders = await _hiveService.getFolders();
      final Map<String, String> localToDriveFolderMap = {'root': appRootFolderId};

      debugPrint('[DriveSync] Reconstructing folder tree on Drive...');
      Future<String> syncFolder(FolderModel folder) async {
        final String localId = folder.id.toString();
        if (localToDriveFolderMap.containsKey(localId)) return localToDriveFolderMap[localId]!;

        String parentDriveId = appRootFolderId;
        if (folder.parentId != null) {
          final parentFolder = localFolders.firstWhereOrNull(
              (f) => f.id.toString() == folder.parentId.toString());
          if (parentFolder != null) {
            parentDriveId = await syncFolder(parentFolder);
          }
        }

        final driveId = await _getOrCreateDriveFolder(driveApi, folder.name, parentId: parentDriveId);
        localToDriveFolderMap[localId] = driveId;
        return driveId;
      }

      for (int i = 0; i < localFolders.length; i++) {
        await syncFolder(localFolders[i]);
        _progressController.add(0.1 + (0.4 * (i + 1) / (localFolders.isEmpty ? 1 : localFolders.length)));
      }

      // Step D & E: Vault File Upload Matrix
      final localFiles = await _hiveService.getFiles();
      debugPrint('[DriveSync] Uploading vault files...');
      for (int i = 0; i < localFiles.length; i++) {
        final file = localFiles[i];

        // Parent Routing Logic
        String? targetDriveFolderId;
        if (file.folderId != null) {
          targetDriveFolderId = localToDriveFolderMap[file.folderId.toString()];
        }
        final String destinationId = targetDriveFolderId ?? uncategorizedFolderId;

        // Byte Stream Transfer
        final Map<String, dynamic> payload = file.toJson();
        final List<int> bytes = utf8.encode(jsonEncode(payload));
        final media = ga.Media(Stream.value(bytes), bytes.length, contentType: 'application/json');

        // Deduplication Check
        final fileName = 'file_${file.id.toString()}.json';
        final query = "name = '${_escapeQuery(fileName)}' and '$destinationId' in parents and trashed = false";
        final existing = await driveApi.files.list(q: query, spaces: 'drive');

        if (existing.files != null && existing.files!.isNotEmpty) {
          // Update Existing - FIX 403: Exclude parents from metadata
          await driveApi.files.update(
            ga.File()..name = fileName..mimeType = 'application/json',
            existing.files!.first.id!,
