          await driveApi.files.create(
            ga.File()
              ..name = fileName
              ..mimeType = 'application/json'
              ..parents = [destinationId],
            uploadMedia: media,
          );
          debugPrint('[DriveSync] Created File: $fileName');
        }

        _progressController.add(0.5 + (0.5 * (i + 1) / (localFiles.isEmpty ? 1 : localFiles.length)));
      }

