import 'dart:io';
import 'package:archive/archive_io.dart';
import 'package:flutter/foundation.dart';
import 'package:google_sign_in/google_sign_in.dart';
import 'package:googleapis/drive/v3.dart' as drive;
import 'package:http/http.dart' as http;
import 'package:path_provider/path_provider.dart';
import 'package:notepad_pro/services/hive_service.dart';
import 'package:notepad_pro/services/auth/auth_service.dart';
import 'package:hive_flutter/hive_flutter.dart';

class SyncService {
  final AuthService _authService;
  final HiveService _hiveService;

  SyncService(this._authService, this._hiveService);

  // Use the broadcast stream from AuthService to fix "Bad state: Stream has already been listened to"
  Stream<GoogleSignInAccount?> get authStateStream => _authService.user;

  Future<GoogleSignInAccount?> signIn() => _authService.signInWithGoogle();
  Future<void> signOut() => _authService.signOut();

  Future<drive.DriveApi?> _getDriveApi() async {
    // Attempt silent sign in first, then interactive if needed
    final GoogleSignInAccount? account = await _authService.signInSilently() ?? await _authService.signInWithGoogle();
    if (account == null) return null;

    final authHeaders = await account.authHeaders;
    final authenticateClient = GoogleAuthClient(authHeaders);
    return drive.DriveApi(authenticateClient);
  }

  /// Backup Logic: Compress Application Documents Directory and upload to Drive
  Future<void> backupToDrive() async {
    final driveApi = await _getDriveApi();
    if (driveApi == null) throw Exception("Could not connect to Google Drive");

    final directory = await getApplicationDocumentsDirectory();
    final zipFile = File('${directory.path}/backup.zip');

    // 1. Create the Zip Archive
    final encoder = ZipFileEncoder();
    encoder.create(zipFile.path);

    final dir = Directory(directory.path);
    final List<FileSystemEntity> entities = dir.listSync(recursive: true);

    for (var entity in entities) {
      if (entity is File) {
        // Avoid zipping the backup zip itself or temp files
        final bool isBackupFile = entity.path.endsWith('backup.zip');
        final bool isLockFile = entity.path.endsWith('.lock');

        if (!isBackupFile && !isLockFile) {
          final relativePath = entity.path.replaceFirst('${directory.path}${Platform.pathSeparator}', '');
          encoder.addFile(entity, relativePath);
        }
      }
    }
    encoder.close();

    // 2. Prepare for Upload
    final bytes = await zipFile.readAsBytes();
    final driveFile = drive.File()
      ..name = 'notepad_pro_backup.zip'
      ..mimeType = 'application/zip';

    final media = drive.Media(
      Stream.value(bytes),
      bytes.length,
      contentType: 'application/zip',
    );

    // 3. Search for existing backup to overwrite
    final list = await driveApi.files.list(
      q: "name = 'notepad_pro_backup.zip' and trashed = false",
      spaces: 'drive',
    );

    if (list.files != null && list.files!.isNotEmpty) {
      // Update existing file
      await driveApi.files.update(driveFile, list.files!.first.id!, uploadMedia: media);
      debugPrint('Backup updated on Google Drive.');
    } else {
      // Create new file
      await driveApi.files.create(driveFile, uploadMedia: media);
      debugPrint('New backup created on Google Drive.');
    }

    // 4. Cleanup
    if (await zipFile.exists()) {
      await zipFile.delete();
    }
  }

  /// Restore Logic: Download zip from Drive and extract to Documents Directory
  Future<void> restoreFromDrive() async {
    final driveApi = await _getDriveApi();
    if (driveApi == null) throw Exception("Could not connect to Google Drive");

    // 1. Find the backup file on Drive
    final list = await driveApi.files.list(
      q: "name = 'notepad_pro_backup.zip' and trashed = false",
      spaces: 'drive',
    );

    if (list.files == null || list.files!.isEmpty) {
      throw Exception("No backup found on Google Drive. Please create a backup first.");
    }

    // 2. Download the file
    final fileId = list.files!.first.id!;
    final drive.Media media = await driveApi.files.get(
      fileId, 
      downloadOptions: drive.DownloadOptions.fullMedia
    ) as drive.Media;

    final List<int> bytes = [];
    await for (final chunk in media.stream) {
      bytes.addAll(chunk);
    }

    // 3. Critical: Close Hive before overwriting local storage files
    await Hive.close();

    // 4. Clear local Documents Directory (to ensure a clean restore)
    final directory = await getApplicationDocumentsDirectory();
    final dir = Directory(directory.path);

    if (await dir.exists()) {
      final entities = dir.listSync();
      for (var entity in entities) {
        try {
          await entity.delete(recursive: true);
        } catch (e) {
          debugPrint('Could not delete ${entity.path}: $e');
        }
      }
    }

    // 5. Extract Zip Archive
    final archive = ZipDecoder().decodeBytes(bytes);
    for (final file in archive) {
      final filename = file.name;
      if (file.isFile) {
        final data = file.content as List<int>;
        File('${directory.path}/$filename')
          ..createSync(recursive: true)
          ..writeAsBytesSync(data);
      } else {
        Directory('${directory.path}/$filename').createSync(recursive: true);
      }
    }

    debugPrint('Restore complete. Hive files replaced.');

    // Note: The app should ideally be restarted or Hive re-initialized here.
    // Since we cannot force a restart easily, the SyncCubit will handle notifying the UI.
  }
}

/// Helper client for Google Authentication headers
class GoogleAuthClient extends http.BaseClient {
  final Map<String, String> _headers;
  final http.Client _client = http.Client();

  GoogleAuthClient(this._headers);

  @override
  Future<http.StreamedResponse> send(http.BaseRequest request) {
    request.headers.addAll(_headers);
    return _client.send(request);
  }
}

