import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';

class ReadNoteScreen extends StatefulWidget {
  final VaultFile file;
  const ReadNoteScreen({super.key, required this.file});

  @override
  State<ReadNoteScreen> createState() => _ReadNoteScreenState();
}

class _ReadNoteScreenState extends State<ReadNoteScreen> {
  Future<pw.Document> _buildPdfDocument({
    PdfPageFormat format = PdfPageFormat.a4,
  }) async {
    final doc = pw.Document();

    final String title = widget.file.title.trim().isEmpty ? 'Untitled' : widget.file.title.trim();
    final String content = widget.file.description.trim().isEmpty ? '(No content)' : widget.file.description.trim();

    final bool isTitleUrdu = _isUrdu(title);
    final bool isBodyUrdu = _isUrdu(content);

    // Load Arabic/Urdu font from Google (Noto Naskh Arabic supports Urdu characters)
    pw.Font? arabicFont;
    if (isTitleUrdu || isBodyUrdu) {
      try {
        arabicFont = await PdfGoogleFonts.notoNaskhArabicRegular();
        debugPrint('Arabic font loaded: OK');
      } catch (e) {
        debugPrint('Font load failed: $e');
        arabicFont = null;
      }
    }

    try {
      doc.addPage(
        pw.Page(
          pageFormat: format.copyWith(
            marginTop: 25 * PdfPageFormat.mm,
            marginBottom: 20 * PdfPageFormat.mm,
            marginLeft: 25 * PdfPageFormat.mm,
            marginRight: 25 * PdfPageFormat.mm,
          ),
          build: (pw.Context ctx) {
            return pw.Column(
              crossAxisAlignment: pw.CrossAxisAlignment.stretch,
              children: [
                // ── TITLE ──────────────────
                pw.Text(
                  title,
                  textDirection: isTitleUrdu ? pw.TextDirection.rtl : pw.TextDirection.ltr,
                  textAlign: isTitleUrdu ? pw.TextAlign.right : pw.TextAlign.left,
                  style: pw.TextStyle(
                    font: isTitleUrdu ? arabicFont : null,
                    fontSize: 20,
                    fontWeight: pw.FontWeight.bold,
                  ),
                ),
                pw.SizedBox(height: 6),
                pw.Divider(color: PdfColors.grey400, thickness: 0.5),
                pw.SizedBox(height: 14),

                // ── BODY CONTENT ───────────
                pw.Expanded(
                  child: pw.Text(
                    content,
                    textDirection: isBodyUrdu ? pw.TextDirection.rtl : pw.TextDirection.ltr,
                    textAlign: pw.TextAlign.justify,
                    style: pw.TextStyle(
                      font: isBodyUrdu ? arabicFont : null,
                      fontSize: 13,
                      lineSpacing: 5,
                    ),
                  ),
                ),

                // ── REFERENCE — ALWAYS BOTTOM
                if (_hasReference()) ...[
                  pw.Divider(color: PdfColors.grey300, thickness: 0.5),
                  pw.SizedBox(height: 8),
                  _buildRefSection(isBodyUrdu, arabicFont),
                ],

                // ── PAGE NUMBER ─────────────
                pw.SizedBox(height: 12),
                pw.Center(
                  child: pw.Text(
                    '${ctx.pageNumber} / ${ctx.pagesCount}',
                    style: const pw.TextStyle(fontSize: 10, color: PdfColors.grey400),
                  ),
                ),
              ],
            );
          },
        ),
      );
    } catch (e) {
      debugPrint('Page error: $e');
      doc.addPage(
        pw.Page(
          build: (_) => pw.Center(
            child: pw.Text(title, style: const pw.TextStyle(fontSize: 16)),
          ),
        ),
      );
    }

    return doc;
  }

  Future<Uint8List> _buildFallbackPdf() async {
    final doc = pw.Document();
    doc.addPage(
      pw.Page(
        build: (_) => pw.Center(
          child: pw.Column(
            mainAxisAlignment: pw.MainAxisAlignment.center,
            children: [
              pw.Text(
                widget.file.title.isNotEmpty ? widget.file.title : 'Note',
                style: pw.TextStyle(fontSize: 20, fontWeight: pw.FontWeight.bold),
              ),
              pw.SizedBox(height: 20),
              pw.Text(
                widget.file.description.isNotEmpty ? widget.file.description : '(No content)',
                style: const pw.TextStyle(fontSize: 13),
              ),
            ],
          ),
        ),
      ),
    );
    return doc.save();
  }

  bool _hasReference() {
    if (widget.file.referenceType == ReferenceType.none) return false;
    final detail = _getReferenceDetailText();
    return detail.trim().isNotEmpty;
  }

  String _getReferenceDetailText() {
    if (widget.file.referenceType == ReferenceType.video) {
      final String vTitle = widget.file.videoTitle ?? 'Video';
      final int h = widget.file.videoRefHours ?? 0;
      final int m = widget.file.videoRefMinutes ?? 0;
      final int s = widget.file.videoRefSeconds ?? 0;
      return '$vTitle (${h}h ${m}m ${s}s)';
    } else if (widget.file.referenceType == ReferenceType.book) {
      final List<String> parts = [];
      if (widget.file.bookName != null && widget.file.bookName!.isNotEmpty) parts.add(widget.file.bookName!);
      if (widget.file.authorName != null && widget.file.authorName!.isNotEmpty) parts.add('by ${widget.file.authorName}');
      if (widget.file.volume != null && widget.file.volume!.isNotEmpty) parts.add('Vol: ${widget.file.volume}');
      if (widget.file.pageNumber != null) parts.add('Page: ${widget.file.pageNumber}');
      if (widget.file.lineNumber != null) parts.add('Line: ${widget.file.lineNumber}');
      return parts.isEmpty ? "" : parts.join(', ');
    }
    return '';
  }

  pw.Widget _buildRefSection(bool isRTL, pw.Font? font) {
    final refType = widget.file.referenceType == ReferenceType.video ? "Video" : "Book";
    final refDetail = _getReferenceDetailText();

    final isVideo = widget.file.referenceType == ReferenceType.video;
    final badgeColor = isVideo ? PdfColors.blue50 : PdfColors.green50;
    final badgeTextColor = isVideo ? PdfColors.blue800 : PdfColors.green800;

    final badge = pw.Container(
      padding: const pw.EdgeInsets.symmetric(horizontal: 6, vertical: 2),
      decoration: pw.BoxDecoration(
        color: badgeColor,
        borderRadius: pw.BorderRadius.circular(4),
      ),
      child: pw.Text(
        refType,
        style: pw.TextStyle(
          fontSize: 10,
          color: badgeTextColor,
          fontWeight: pw.FontWeight.bold,
        ),
      ),
    );

    final detailText = pw.Text(
      refDetail,
      style: pw.TextStyle(
        font: isRTL ? font : null,
        fontSize: 10, 
        color: PdfColors.grey600,
      ),
    );

    final gap = pw.SizedBox(width: 8);

    return pw.Row(
      mainAxisAlignment: isRTL ? pw.MainAxisAlignment.end : pw.MainAxisAlignment.start,
      children: isRTL ? [detailText, gap, badge] : [badge, gap, detailText],
    );
  }

  bool _isUrdu(String text) {
    if (text.trim().isEmpty) return false;
    int u = 0, t = 0;
    for (final r in text.runes) {
      if (r <= 32 || (r >= 48 && r <= 57)) continue;
      t++;
      if ((r >= 0x0600 && r <= 0x06FF) || (r >= 0xFB50 && r <= 0xFDFF) || (r >= 0xFE70 && r <= 0xFEFF)) u++;
    }
    return t > 0 && (u / t) >= 0.3;
  }

  @override
  Widget build(BuildContext context) {
    final textDirection = TextDirectionUtils.getDirection(widget.file.description);
    final textAlign = TextDirectionUtils.getTextAlign(widget.file.description);

    return Scaffold(
      backgroundColor: const Color(0xFFF5F0FF),
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: Color(0xFF6C5CE7)),
          onPressed: () => context.pop(),
        ),
        title: Text(
          widget.file.title,
          style: const TextStyle(
            fontSize: 17,
            fontWeight: FontWeight.w500,
            color: Color(0xFF2D2540),
          ),
          textDirection: TextDirectionUtils.getDirection(widget.file.title),
        ),
        actions: [
          IconButton(
            icon: const Icon(Icons.print_outlined, color: Color(0xFF6C5CE7)),
            onPressed: () async {
              debugPrint('[PrintEngine] Directly firing native Android OS Print dialog...');
              await Printing.layoutPdf(
                name: widget.file.title.isNotEmpty ? widget.file.title : 'Note',
                format: PdfPageFormat.a4,
                onLayout: (PdfPageFormat format) async {
                  try {
                    final doc = await _buildPdfDocument(format: format);
                    final bytes = await doc.save();

                    debugPrint('PDF bytes size: ${bytes.length}');
                    if (bytes.isNotEmpty) {
                      debugPrint('PDF starts with: ${String.fromCharCodes(bytes.take(4))}');
                    }

                    if (bytes.isEmpty) {
                      throw Exception('PDF bytes empty');
                    }
                    return bytes;
                  } catch (e) {
                    debugPrint('onLayout error: $e');
