                          debugPrint('onLayout error (bottom): $e');
                          return await _buildFallbackPdf();
                        }
                      },
                    );
                  },
                  icon: const Icon(Icons.print_outlined, size: 18),
                  label: const Text("Print"),
                  style: OutlinedButton.styleFrom(
                    foregroundColor: const Color(0xFF6C5CE7),
