      referenceTitle = "Video Reference";
      icon = Icons.play_circle_outline;
      details = widget.file.videoTitle;
      if (widget.file.videoRefHours != null || widget.file.videoRefMinutes != null || widget.file.videoRefSeconds != null) {
        details = "${details ?? "Video"} at ${widget.file.videoRefHours ?? 0}h ${widget.file.videoRefMinutes ?? 0}m ${widget.file.videoRefSeconds ?? 0}s";
      }
    } else if (widget.file.referenceType == ReferenceType.book) {
      referenceTitle = "Book Reference";
      icon = Icons.book_outlined;
      details = widget.file.bookName;
      if (widget.file.authorName != null) details = "${details ?? "Book"} by ${widget.file.authorName}";
    }

