  bool _hasReference() {
    if (widget.file.referenceType == ReferenceType.none) return false;
    final detail = _getReferenceDetailText();
    return detail.trim().isNotEmpty;
  }

  String _getReferenceDetailText() {
    if (widget.file.referenceType == ReferenceType.video) {
      final String vTitle = widget.file.videoTitle ?? 'Video';
      final int h = widget.file.videoRefHours ?? 0;
      final int m = widget.file.videoRefMinutes ?? 0;
      final int s = widget.file.videoRefSeconds ?? 0;
      return '$vTitle (${h}h ${m}m ${s}s)';
    } else if (widget.file.referenceType == ReferenceType.book) {
      final List<String> parts = [];
      if (widget.file.bookName != null && widget.file.bookName!.isNotEmpty) parts.add(widget.file.bookName!);
      if (widget.file.authorName != null && widget.file.authorName!.isNotEmpty) parts.add('by ${widget.file.authorName}');
      if (widget.file.volume != null && widget.file.volume!.isNotEmpty) parts.add('Vol: ${widget.file.volume}');
      if (widget.file.pageNumber != null) parts.add('Page: ${widget.file.pageNumber}');
      if (widget.file.lineNumber != null) parts.add('Line: ${widget.file.lineNumber}');
      return parts.isEmpty ? "" : parts.join(', ');
    }
    return '';
  }

  pw.Widget _buildRefSection(bool isRTL, pw.Font? font) {
    final refType = widget.file.referenceType == ReferenceType.video ? "Video" : "Book";
    final refDetail = _getReferenceDetailText();

    final isVideo = widget.file.referenceType == ReferenceType.video;
    final badgeColor = isVideo ? PdfColors.blue50 : PdfColors.green50;
    final badgeTextColor = isVideo ? PdfColors.blue800 : PdfColors.green800;

    final badge = pw.Container(
      padding: const pw.EdgeInsets.symmetric(horizontal: 6, vertical: 2),
      decoration: pw.BoxDecoration(
