class GoogleDriveSyncService {
  final AuthService _authService;
  final HiveService _hiveService;

  GoogleDriveSyncService(this._authService, this._hiveService);

  Stream<GoogleSignInAccount?> get authStateStream => _authService.user;

  Future<GoogleSignInAccount?> signIn() => _authService.signInWithGoogle();
  Future<void> signOut() => _authService.signOut();

  Future<drive.DriveApi?> _getDriveApi() async {
    final GoogleSignInAccount? account = await _authService.signInSilently() ?? await _authService.signInWithGoogle();
    if (account == null) return null;

    final authHeaders = await account.authHeaders;
    final authenticateClient = GoogleAuthClient(authHeaders);
    return drive.DriveApi(authenticateClient);
  }

  /// 1. Multi-Level Nested Folder Backup Logic
  Future<void> backupToDrive() async {
    final driveApi = await _getDriveApi();
    if (driveApi == null) throw Exception("Could not connect to Google Drive");

    // A. Ensure App Root Folder exists
    final rootFolderId = await _getOrCreateFolder(driveApi, 'NotepadPro_Backup');

    // B. Fetch all local data
    final folders = await _hiveService.getFolders();
    final notes = await _hiveService.getNotes();

    // C. Recursive Folder Mapping
    // This map tracks Hive Folder ID -> Google Drive Folder ID
    final Map<String, String> hiveToDriveFolderId = {};

    Future<String> ensureFolderOnDrive(FolderModel hiveFolder) async {
      if (hiveToDriveFolderId.containsKey(hiveFolder.id)) {
        return hiveToDriveFolderId[hiveFolder.id]!;
      }

      String parentDriveId;
      if (hiveFolder.parentId != null) {
        final parentHiveFolder = folders.firstWhereOrNull((f) => f.id == hiveFolder.parentId);
        if (parentHiveFolder != null) {
          parentDriveId = await ensureFolderOnDrive(parentHiveFolder);
        } else {
          parentDriveId = rootFolderId;
        }
      } else {
        parentDriveId = rootFolderId;
      }

      // Check if we already have a driveFileId stored locally to reuse
      String driveId;
      if (hiveFolder.driveFileId != null) {
        // Verify it still exists and has the correct parent
        final existing = await _verifyFolder(driveApi, hiveFolder.driveFileId!, hiveFolder.name, parentDriveId);
        if (existing != null) {
          driveId = existing;
        } else {
          driveId = await _getOrCreateFolder(driveApi, hiveFolder.name, parentId: parentDriveId);
        }
      } else {
        driveId = await _getOrCreateFolder(driveApi, hiveFolder.name, parentId: parentDriveId);
      }

      hiveToDriveFolderId[hiveFolder.id] = driveId;
      return driveId;
    }

    // Process all folders to build the hierarchy on Drive
    for (final folder in folders) {
      final driveId = await ensureFolderOnDrive(folder);
      if (folder.driveFileId != driveId) {
        // Update Hive with the Drive ID for future syncs
        await _hiveService.folderBox.put(folder.id, folder.copyWith(driveFileId: driveId));
      }
    }

    // D. Backup Folders Metadata (as a snapshot for quick structure recovery)
    final updatedFolders = await _hiveService.getFolders();
    final foldersJson = jsonEncode(updatedFolders.map((f) => f.toJson()).toList());
    await _uploadFile(driveApi, 'folders_metadata.json', foldersJson, rootFolderId);

    // E. Uncategorized Handler: For loose notes
    final uncategorizedDriveId = await _getOrCreateFolder(driveApi, 'Uncategorized Notes', parentId: rootFolderId);

    // F. Notes Injection into Drive
    for (final note in notes) {
      final targetDriveId = (note.folderId != null)
          ? (hiveToDriveFolderId[note.folderId] ?? uncategorizedDriveId)
          : uncategorizedDriveId;

      final noteJson = jsonEncode(note.toJson());
      await _uploadFile(driveApi, '${note.id}.json', noteJson, targetDriveId);
    }

    debugPrint('Recursive multi-level backup completed successfully.');
  }

  /// 2. Deep Structural Restore Engine
  Future<void> restoreBackupFromDrive() async {
    final driveApi = await _getDriveApi();
    if (driveApi == null) throw Exception("Could not connect to Google Drive");

    // A. Find App Root Folder
    final rootFolderId = await _findFolder(driveApi, 'NotepadPro_Backup');
    if (rootFolderId == null) throw Exception("No backup found on Google Drive.");

    // B. Reconstruct the Folders box into Hive FIRST
    final foldersMetadataId = await _findFile(driveApi, 'folders_metadata.json', rootFolderId);
    if (foldersMetadataId == null) throw Exception("Backup metadata missing. Cannot reconstruct hierarchy.");

    final metadataContent = await _downloadFileContent(driveApi, foldersMetadataId);
    final List<dynamic> folderList = jsonDecode(metadataContent);

    final Map<String, FolderModel> hiveFolderMap = {
      for (var json in folderList) json['id']: FolderModel.fromJson(json)
    };

    // Safely clear and update Hive Folders to establish the structure
    await _hiveService.folderBox.clear();
    await _hiveService.folderBox.putAll(hiveFolderMap);
    debugPrint('Step 1: Folder hierarchy nodes established in Hive.');

    // C. Wipe Note Box for clean injection
    await _hiveService.noteBox.clear();

    // D. Top-Down Tree Traversal
    // Map Drive Folder ID -> Hive Folder ID for perfect linkage
    final Map<String, String?> driveToHiveMap = {
      for (var f in hiveFolderMap.values) if (f.driveFileId != null) f.driveFileId!: f.id
    };

    Future<void> crawlDriveRecursively(String driveFolderId, String? currentHiveFolderId) async {
      final driveFiles = await _listFiles(driveApi, driveFolderId);

      for (final file in driveFiles) {
        if (file.mimeType == 'application/vnd.google-apps.folder') {
          // Identify if this folder represents a Hive folder or 'Uncategorized'
          String? nextHiveId;
          if (file.name == 'Uncategorized Notes') {
            nextHiveId = null; 
          } else {
            nextHiveId = driveToHiveMap[file.id];
            // Robust fallback: Match by name if ID mapping fails
            if (nextHiveId == null) {
              final match = hiveFolderMap.values.firstWhereOrNull(
                (f) => f.name == file.name && f.parentId == currentHiveFolderId
              );
              nextHiveId = match?.id;
            }
          }
          await crawlDriveRecursively(file.id!, nextHiveId);
        } else if (file.name!.endsWith('.json') && file.name != 'folders_metadata.json') {
          // It's a note JSON file - restore it
          try {
            final content = await _downloadFileContent(driveApi, file.id!);
            final noteJson = jsonDecode(content);
            final note = NoteModel.fromJson(noteJson).copyWith(
              folderId: currentHiveFolderId, // Ensure it links to the folder it was found in
              isSynced: true,
            );
            await _hiveService.noteBox.put(note.id, note);
          } catch (e) {
            debugPrint('Error restoring note ${file.name}: $e');
          }
        }
      }
    }

    await crawlDriveRecursively(rootFolderId, null);

    // Notify UI
    _hiveService.setInitialized(true);
    debugPrint('Step 2: Deep structural restore completed.');
  }

  // Helper Methods
  Future<String> _getOrCreateFolder(drive.DriveApi api, String name, {String? parentId}) async {
    String query = "name = '$name' and mimeType = 'application/vnd.google-apps.folder' and trashed = false";
    if (parentId != null) query += " and '$parentId' in parents";

    final list = await api.files.list(q: query, spaces: 'drive');
    if (list.files != null && list.files!.isNotEmpty) {
      return list.files!.first.id!;
    }

    final folder = drive.File()
      ..name = name
      ..mimeType = 'application/vnd.google-apps.folder';
    if (parentId != null) folder.parents = [parentId];

    final created = await api.files.create(folder);
    return created.id!;
  }

  Future<String?> _verifyFolder(drive.DriveApi api, String driveId, String expectedName, String expectedParentId) async {
    try {
      final file = await api.files.get(driveId, $fields: 'id,name,parents,trashed') as drive.File;
      if (file.trashed == true || file.name != expectedName) return null;
      if (file.parents != null && file.parents!.contains(expectedParentId)) {
        return file.id;
      }
      return null;
    } catch (e) {
      return null;
    }
  }

  Future<String?> _findFolder(drive.DriveApi api, String name, {String? parentId}) async {
    String query = "name = '$name' and mimeType = 'application/vnd.google-apps.folder' and trashed = false";
    if (parentId != null) query += " and '$parentId' in parents";

    final list = await api.files.list(q: query, spaces: 'drive');
    return (list.files != null && list.files!.isNotEmpty) ? list.files!.first.id : null;
  }

  Future<String?> _findFile(drive.DriveApi api, String name, String parentId) async {
    final query = "name = '$name' and '$parentId' in parents and trashed = false";
    final list = await api.files.list(q: query, spaces: 'drive');
    return (list.files != null && list.files!.isNotEmpty) ? list.files!.first.id : null;
  }

  Future<List<drive.File>> _listFiles(drive.DriveApi api, String folderId) async {
    final list = await api.files.list(
      q: "'$folderId' in parents and trashed = false", 
      spaces: 'drive',
      $fields: 'files(id, name, mimeType, parents, trashed)'
    );
    return list.files ?? [];
  }

  Future<void> _uploadFile(drive.DriveApi api, String name, String content, String parentId) async {
    final bytes = utf8.encode(content);
    final media = drive.Media(Stream.value(bytes), bytes.length);

    final existingId = await _findFile(api, name, parentId);
    if (existingId != null) {
      // Use an empty File object for updates to avoid forbidden field errors (like 'parents')
      await api.files.update(drive.File(), existingId, uploadMedia: media);
    } else {
      final driveFile = drive.File()
        ..name = name
        ..parents = [parentId]
        ..mimeType = 'application/json';
      await api.files.create(driveFile, uploadMedia: media);
    }
  }

  Future<String> _downloadFileContent(drive.DriveApi api, String fileId) async {
    final media = await api.files.get(fileId, downloadOptions: drive.DownloadOptions.fullMedia) as drive.Media;
    final List<int> bytes = [];
    await for (final chunk in media.stream) {
      bytes.addAll(chunk);
    }
    return utf8.decode(bytes);
  }
}

class GoogleAuthClient extends http.BaseClient {
  final Map<String, String> _headers;
  final http.Client _client = http.Client();

  GoogleAuthClient(this._headers);

  @override
  Future<http.StreamedResponse> send(http.BaseRequest request) {
    request.headers.addAll(_headers);
    return _client.send(request);
  }
}

