import 'dart:io';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';
import 'package:path_provider/path_provider.dart';

class PaperSize {
  final String name;
  final PdfPageFormat format;
  final String dimensions;
  const PaperSize(this.name, this.format, this.dimensions);
}

class PdfPreviewScreen extends StatefulWidget {
  final String noteTitle;
  final String noteContent;
  final bool hasReference;
  final String? referenceType;
  final String? referenceDetail;
  final bool hasSensitiveContent;

  const PdfPreviewScreen({
    super.key,
    required this.noteTitle,
    required this.noteContent,
    this.hasReference = false,
    this.referenceType,
    this.referenceDetail,
    this.hasSensitiveContent = false,
  });

  @override
  State<PdfPreviewScreen> createState() => _PdfPreviewScreenState();
}

class _PdfPreviewScreenState extends State<PdfPreviewScreen> {
  // Printer state
  List<Printer> _availablePrinters = [];
  Printer? _selectedPrinter;
  bool _loadingPrinters = false;

  // Paper sizes
  List<PaperSize> _availablePaperSizes = [];
  PdfPageFormat _selectedFormat = PdfPageFormat.a4;
  String _selectedFormatName = 'ISO A4';

  // Orientation
  bool _isLandscape = false;

  // Copies
  int _copies = 1;

  // More options
  bool _showMoreOptions = false;

  // PDF document
  Future<pw.Document>? _pdfFuture;

  // Loading
  bool _isSaving = false;

  @override
  void initState() {
    super.initState();
    _loadPrinters();
    _buildPdf();
  }

  Future<void> _loadPrinters() async {
    setState(() => _loadingPrinters = true);
    try {
      final printers = await Printing.listPrinters();
      setState(() {
        _availablePrinters = printers;
        _selectedPrinter = printers.isNotEmpty ? printers.first : null;
        _loadingPrinters = false;
      });
      if (_selectedPrinter != null) {
        await _loadPaperSizes(_selectedPrinter!);
      } else {
        _setDefaultPaperSizes();
      }
    } catch (e) {
      if (mounted) setState(() => _loadingPrinters = false);
      _setDefaultPaperSizes();
    }
  }

  Future<void> _loadPaperSizes(Printer printer) async {
    try {
      // In a real scenario, we could query printer capabilities
      // For now, we use a comprehensive list of standard sizes
      _setDefaultPaperSizes();
    } catch (e) {
      _setDefaultPaperSizes();
    }
  }

  void _setDefaultPaperSizes() {
    _availablePaperSizes = [
      const PaperSize('ISO A4', PdfPageFormat.a4, '210 × 297 mm'),
      const PaperSize('US Letter', PdfPageFormat.letter, '216 × 279 mm'),
      const PaperSize('US Legal', PdfPageFormat.legal, '216 × 356 mm'),
      const PaperSize('ISO A3', PdfPageFormat.a3, '297 × 420 mm'),
      const PaperSize('ISO A5', PdfPageFormat.a5, '148 × 210 mm'),
      PaperSize('US Executive', const PdfPageFormat(184 * PdfPageFormat.mm, 267 * PdfPageFormat.mm), '184 × 267 mm'),
      PaperSize('B5 (JIS)', const PdfPageFormat(176 * PdfPageFormat.mm, 250 * PdfPageFormat.mm), '176 × 250 mm'),
      PaperSize('B4 (JIS)', const PdfPageFormat(257 * PdfPageFormat.mm, 364 * PdfPageFormat.mm), '257 × 364 mm'),
      PaperSize('Tabloid', const PdfPageFormat(279 * PdfPageFormat.mm, 432 * PdfPageFormat.mm), '279 × 432 mm'),
      PaperSize('Folio', const PdfPageFormat(210 * PdfPageFormat.mm, 330 * PdfPageFormat.mm), '210 × 330 mm'),
      PaperSize('Statement', const PdfPageFormat(140 * PdfPageFormat.mm, 216 * PdfPageFormat.mm), '140 × 216 mm'),
      PaperSize('Quarto', const PdfPageFormat(215 * PdfPageFormat.mm, 275 * PdfPageFormat.mm), '215 × 275 mm'),
    ];
    if (mounted) setState(() {});
  }

  void _buildPdf() {
    setState(() {
      _pdfFuture = _generatePdf();
    });
  }

  bool _isUrduText(String text) {
    if (text.isEmpty) return false;
    final urduRegex = RegExp(r'[\u0600-\u06FF]');
    return urduRegex.hasMatch(text);
  }

  Future<pw.Document> _generatePdf() async {
    final doc = pw.Document();

    // NULL SAFETY — content empty ho to placeholder
    final title = widget.noteTitle.isNotEmpty ? widget.noteTitle : 'Untitled';
    final content = widget.noteContent.isNotEmpty ? widget.noteContent : '(No content)';

    final isUrdu = _isUrduText(content);

    // FONT — try/catch se load karein
    pw.Font? urduFont;
    if (isUrdu) {
      try {
        final fontData = await rootBundle.load('assets/fonts/NotoNastaliqUrdu-Regular.ttf');
        urduFont = pw.Font.ttf(fontData);
      } catch (e) {
        debugPrint('Font load error: $e');
        // Font load na ho to null rahega
        // PDF bhi banega, sirf font default hoga
      }
    }

    try {
      var format = _selectedFormat;
      if (_isLandscape) {
        format = PdfPageFormat(
          format.height, format.width,
          marginTop: 20 * PdfPageFormat.mm,
          marginBottom: 20 * PdfPageFormat.mm,
          marginLeft: 20 * PdfPageFormat.mm,
          marginRight: 20 * PdfPageFormat.mm);
      } else {
        format = format.copyWith(
          marginTop: 20 * PdfPageFormat.mm,
          marginBottom: 20 * PdfPageFormat.mm,
          marginLeft: 20 * PdfPageFormat.mm,
          marginRight: 20 * PdfPageFormat.mm);
      }

      doc.addPage(
        pw.Page(
          pageFormat: format,
          build: (pw.Context ctx) {
            return pw.Column(
              crossAxisAlignment: isUrdu ? pw.CrossAxisAlignment.end : pw.CrossAxisAlignment.start,
              children: [
                pw.Text(title,
                  textDirection: isUrdu ? pw.TextDirection.rtl : pw.TextDirection.ltr,
                  style: pw.TextStyle(
                    font: urduFont,
                    fontSize: 18,
                    fontWeight: pw.FontWeight.bold)),
                pw.Divider(),
                pw.SizedBox(height: 8),
                pw.Text(content,
                  textDirection: isUrdu ? pw.TextDirection.rtl : pw.TextDirection.ltr,
                  textAlign: isUrdu ? pw.TextAlign.right : pw.TextAlign.left,
                  style: pw.TextStyle(
                    font: urduFont,
                    fontSize: 12,
                    lineSpacing: 1.5)),
              ],
            );
          },
        ),
      );
    } catch (e) {
      debugPrint('PDF generation error: $e');
      // Error hone par bhi empty page add karein
      // taake "Bad state: No element" na aaye
      doc.addPage(
        pw.Page(
          build: (_) => pw.Center(
            child: pw.Text('PDF generation failed: $e',
              style: pw.TextStyle(fontSize: 12))),
        ),
      );
    }

    return doc;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFE8E8E8),
      body: Column(children: [
        _buildHeader(),
        _buildOptions(),
        _buildMoreOptionsToggle(),
        if (_showMoreOptions) _buildMoreOptions(),
