  }

  Widget _buildOptions() {
    return Container(
      color: Colors.white,
      padding: const EdgeInsets.symmetric(horizontal: 14),
      child: Column(children: [
        _optionRow(
          icon: Icons.copy_outlined,
          label: "Copies",
          trailing: Row(children: [
            _counterBtn("−", const Color(0xFFF0F0F0),
              const Color(0xFF555555),
              () { if (_copies > 1) setState(() => _copies--); }),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 10),
              child: Text("$_copies",
                style: const TextStyle(fontSize: 13,
                  fontWeight: FontWeight.w500,
                  color: Color(0xFF1A1A1A)))),
            _counterBtn("+", const Color(0xFFE3F2FD),
              const Color(0xFF1565C0),
              () { if (_copies < 99) setState(() => _copies++); }),
          ]),
        ),
        const Divider(height: 1, color: Color(0xFFF8F8F8), thickness: 0.5),
        _optionRow(
          icon: Icons.description_outlined,
          label: "Paper size",
          trailing: GestureDetector(
            onTap: _showPaperSizeSheet,
            child: _chip("$_selectedFormatName  ▾"),
          ),
        ),
        const Divider(height: 1, color: Color(0xFFF8F8F8), thickness: 0.5),
        _optionRow(
          icon: Icons.screen_rotation_outlined,
          label: "Orientation",
          trailing: GestureDetector(
            onTap: () {
              setState(() => _isLandscape = !_isLandscape);
              _buildPdf();
            },
            child: _chip(_isLandscape ? "⬜ Landscape" : "📄 Portrait"),
          ),
        ),
      ]),
    );
  }

  Widget _buildMoreOptionsToggle() {
    return GestureDetector(
      onTap: () => setState(() => _showMoreOptions = !_showMoreOptions),
      child: Container(
        color: Colors.white,
        padding: const EdgeInsets.symmetric(vertical: 8),
