                size: 14, color: const Color(0xFF1565C0)),
          ],
        ),
      ),
    );
  }

  Widget _buildMoreOptions() {
    return Container(
      color: Colors.white,
      padding: const EdgeInsets.symmetric(horizontal: 14),
      child: Column(children: [
        _optionRow(
          label: "Color mode",
          trailing: _chip("Color ▾"),
        ),
        _optionRow(
          label: "Quality",
          trailing: _chip("Standard ▾"),
        ),
        const SizedBox(height: 10),
      ]),
