  }

  void _showPaperSizeSheet() {
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.white,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(16))),
      builder: (ctx) => DraggableScrollableSheet(
        initialChildSize: 0.6,
        minChildSize: 0.4,
        maxChildSize: 0.9,
        expand: false,
        builder: (_, scrollController) => Column(children: [
          Container(
            margin: const EdgeInsets.only(top: 8, bottom: 4),
            width: 32, height: 4,
            decoration: BoxDecoration(color: const Color(0xFFD0C8E8), borderRadius: BorderRadius.circular(2)),
          ),
          const Text("PAPER SIZE CHUNEIN",
            style: TextStyle(fontSize: 10, fontWeight: FontWeight.w500, color: Color(0xFF9B8DB8), letterSpacing: 0.5)),
          const SizedBox(height: 8),
          Expanded(
            child: ListView.separated(
              controller: scrollController,
              itemCount: _availablePaperSizes.length,
              separatorBuilder: (_, __) => const Divider(height: 1, color: Color(0xFFF5F0FF), indent: 14, endIndent: 14, thickness: 0.5),
              itemBuilder: (_, i) {
                final ps = _availablePaperSizes[i];
                final isSelected = _selectedFormatName == ps.name;
                return InkWell(
                  onTap: () {
                    setState(() {
                      _selectedFormat = ps.format;
                      _selectedFormatName = ps.name;
                    });
                    Navigator.pop(ctx);
                    _buildPdf();
                  },
                  child: Container(
                    color: isSelected ? const Color(0xFFF5F0FF) : Colors.white,
                    padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                    child: Row(children: [
                      Expanded(child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(ps.name,
                            style: TextStyle(fontSize: 14, fontWeight: isSelected ? FontWeight.w500 : FontWeight.w400, color: isSelected ? const Color(0xFF6C5CE7) : const Color(0xFF2D2540))),
                          Text(ps.dimensions, style: const TextStyle(fontSize: 11, color: Color(0xFF9B8DB8))),
                        ],
                      )),
                      if (isSelected) const Icon(Icons.check, size: 18, color: Color(0xFF6C5CE7)),
                    ]),
                  ),
                );
              },
            ),
          ),
        ]),
      ),
    );
