  Widget _buildPreview() {
    return Container(
      color: const Color(0xFFE8E8E8),
      padding: const EdgeInsets.all(14),
      child: Column(children: [
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            const Text("Preview", style: TextStyle(fontSize: 11, fontWeight: FontWeight.w500, color: Color(0xFF888888))),
            Text(_isLandscape ? "Landscape View" : "Portrait View", style: const TextStyle(fontSize: 11, color: Color(0xFF888888))),
          ],
        ),
        const SizedBox(height: 8),
        Expanded(
          child: FutureBuilder<pw.Document>(
            future: _pdfFuture,
            builder: (context, snapshot) {
              // Loading state
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const Center(
                  child: CircularProgressIndicator(
                    valueColor: AlwaysStoppedAnimation(Color(0xFF1565C0)),
                    strokeWidth: 2));
              }

              // Error state
              if (snapshot.hasError || !snapshot.hasData) {
                return Center(
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      const Icon(Icons.error_outline, color: Colors.red, size: 32),
                      const SizedBox(height: 8),
                      Text(
                        'Preview load nahi hua\n${snapshot.error ?? ""}',
                        textAlign: TextAlign.center,
                        style: const TextStyle(fontSize: 12, color: Colors.grey)),
                      const SizedBox(height: 12),
                      TextButton(
                        onPressed: () => setState(() => _pdfFuture = _generatePdf()),
                        child: const Text('Dobara try karein')),
                    ],
                  ),
                );
              }

              // Success state
              return PdfPreview(
                build: (_) async {
                  final doc = await _generatePdf();
                  return doc.save();
                },
                allowPrinting: false,
                allowSharing: false,
                canChangePageFormat: false,
                canChangeOrientation: false,
                canDebug: false,
              );
            },
          ),
        ),
      ]),
    );
