import 'dart:typed_data';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';
import 'package:notepad_pro/domain/entities/vault_file.dart';
import 'package:go_router/go_router.dart';

class PdfPreviewScreen extends StatelessWidget {
  final VaultFile file;

  const PdfPreviewScreen({super.key, required this.file});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        iconTheme: const IconThemeData(color: Color(0xFF6C5CE7)),
        title: Text(
          file.title.isNotEmpty ? file.title : 'PDF Preview',
          style: const TextStyle(
            color: Color(0xFF2D2540), 
            fontSize: 16, 
            fontWeight: FontWeight.w600
          ),
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
        ),
        leading: IconButton(
          icon: const Icon(Icons.close),
          onPressed: () => context.pop(),
        ),
      ),
      body: PdfPreview(
        build: (format) => generatePdfReport(format, file),
        allowPrinting: true,
        allowSharing: true,
        canChangePageFormat: true,
        canChangeOrientation: true,
        initialPageFormat: PdfPageFormat.a4,
        loadingWidget: const Center(
          child: CircularProgressIndicator(
            valueColor: AlwaysStoppedAnimation(Color(0xFF6C5CE7)),
          ),
        ),
        // Sanitize filename
        pdfFileName: '${file.title.replaceAll(RegExp(r'[^\w\s-]'), '')}.pdf',
        previewPageDecoration: BoxDecoration(
          color: Colors.white,
          border: Border.all(color: Colors.grey.shade300, width: 0.5),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.05),
              blurRadius: 10,
              offset: const Offset(0, 5),
            ),
          ],
        ),
      ),
    );
  }

  /// Bulletproof Type-Safe PDF Document Generation
  Future<Uint8List> generatePdfReport(PdfPageFormat format, VaultFile file) async {
    final doc = pw.Document();

    // 1. Safe extraction with strict null-aware defaults
    final String titleStr = file.title.isNotEmpty ? file.title : 'Untitled';
    final String contentStr = file.description.isNotEmpty ? file.description : '(No content)';

    // 2. Language & Direction Detection
    final bool isTitleUrdu = _isUrdu(titleStr);
    final bool isContentUrdu = _isUrdu(contentStr);

    // 3. Load Urdu Font (Noto Nastaliq)
    pw.Font? urduFont;
    try {
      final fontData = await rootBundle.load('assets/fonts/NotoNastaliqUrdu-Regular.ttf');
      urduFont = pw.Font.ttf(fontData);
    } catch (e) {
      debugPrint('[PDF] Urdu font load failed: $e');
    }

    // 4. Document Construction
    doc.addPage(
      pw.MultiPage(
        pageFormat: format,
        // Global direction based on content
        textDirection: isContentUrdu ? pw.TextDirection.rtl : pw.TextDirection.ltr,
        margin: const pw.EdgeInsets.all(20 * PdfPageFormat.mm),
        build: (pw.Context context) {
          final List<pw.Widget> elements = [];

          // ── TITLE ──────────────────────────
          elements.add(
            pw.Container(
              width: double.infinity,
              child: pw.Text(
                titleStr,
                textDirection: isTitleUrdu ? pw.TextDirection.rtl : pw.TextDirection.ltr,
                textAlign: isTitleUrdu ? pw.TextAlign.right : pw.TextAlign.left,
                softWrap: true,
                style: pw.TextStyle(
                  font: isTitleUrdu ? urduFont : null,
                  fontSize: 22,
                  fontWeight: pw.FontWeight.bold,
                  color: PdfColors.black,
                ),
              ),
            ),
          );

          elements.add(pw.SizedBox(height: 5));
          elements.add(pw.Divider(thickness: 1, color: PdfColors.grey300));
          elements.add(pw.SizedBox(height: 15));

          // ── CONTENT ────────────────────────
          elements.add(
            pw.Container(
              width: double.infinity,
              child: pw.Text(
                contentStr,
                textDirection: isContentUrdu ? pw.TextDirection.rtl : pw.TextDirection.ltr,
                textAlign: pw.TextAlign.justify,
                softWrap: true,
                style: pw.TextStyle(
                  font: isContentUrdu ? urduFont : null,
                  fontSize: 13,
                  lineSpacing: 6,
                  color: PdfColors.black,
                ),
              ),
            ),
          );

          // ── REFERENCE SECTION ──────────────
          if (file.referenceType != ReferenceType.none) {
            elements.add(pw.SizedBox(height: 30));
            elements.add(pw.Divider(thickness: 0.5, color: PdfColors.grey300));
            elements.add(pw.SizedBox(height: 10));

            if (file.referenceType == ReferenceType.video) {
              final String vTitle = file.videoTitle ?? 'Video';
              final int h = file.videoRefHours ?? 0;
              final int m = file.videoRefMinutes ?? 0;
              final int s = file.videoRefSeconds ?? 0;
              final bool vUrdu = _isUrdu(vTitle);

              elements.add(
                pw.Row(
                  mainAxisAlignment: isContentUrdu ? pw.MainAxisAlignment.end : pw.MainAxisAlignment.start,
                  children: [
                    pw.Text('Video: ', style: pw.TextStyle(fontWeight: pw.FontWeight.bold, fontSize: 10)),
                    pw.Text(
                      '$vTitle (${h}h ${m}m ${s}s)',
                      style: pw.TextStyle(
                        font: vUrdu ? urduFont : null, 
                        fontSize: 10, 
                        color: PdfColors.grey700
                      ),
                    ),
                  ],
                ),
              );
            } else if (file.referenceType == ReferenceType.book) {
              final List<String> bookParts = [];
              if (file.bookName != null && file.bookName!.isNotEmpty) bookParts.add(file.bookName!);
              if (file.authorName != null && file.authorName!.isNotEmpty) bookParts.add('by ${file.authorName}');
              if (file.volume != null && file.volume!.isNotEmpty) bookParts.add('Vol: ${file.volume}');
              if (file.pageNumber != null) bookParts.add('Page: ${file.pageNumber}');
              if (file.lineNumber != null) bookParts.add('Line: ${file.lineNumber}');

              final String bookText = bookParts.isEmpty ? 'N/A' : bookParts.join(', ');
              final bool bUrdu = _isUrdu(bookText);

              elements.add(
                pw.Row(
                  crossAxisAlignment: pw.CrossAxisAlignment.start,
                  mainAxisAlignment: isContentUrdu ? pw.MainAxisAlignment.end : pw.MainAxisAlignment.start,
                  children: [
                    pw.Text('Book: ', style: pw.TextStyle(fontWeight: pw.FontWeight.bold, fontSize: 10)),
                    pw.Expanded(
                      child: pw.Text(
                        bookText,
                        style: pw.TextStyle(
                          font: bUrdu ? urduFont : null, 
                          fontSize: 10, 
                          color: PdfColors.grey700
                        ),
                        softWrap: true,
                      ),
                    ),
                  ],
                ),
              );
            }
          }

          return elements;
        },
        footer: (pw.Context context) {
          return pw.Container(
            alignment: pw.Alignment.center,
            margin: const pw.EdgeInsets.only(top: 10),
            child: pw.Text(
              '${context.pageNumber} / ${context.pagesCount}',
              style: const pw.TextStyle(fontSize: 9, color: PdfColors.grey500),
            ),
          );
        },
      ),
    );

    return doc.save();
  }

  /// Helper for Language Detection
  bool _isUrdu(String text) {
    if (text.trim().isEmpty) return false;
    int urduCount = 0;
    int totalCount = 0;
    for (final char in text.runes) {
      if (char > 32) {
        totalCount++;
        // Arabic/Urdu Unicode blocks
        if ((char >= 0x0600 && char <= 0x06FF) ||
            (char >= 0xFB50 && char <= 0xFDFF) ||
            (char >= 0xFE70 && char <= 0xFEFF)) {
          urduCount++;
        }
      }
    }
    if (totalCount == 0) return false;
    // Treat as Urdu if more than 30% characters are in Urdu range
    return (urduCount / totalCount) > 0.3;
  }
}

